#!/usr/bin/env python3
"""Generate BIEK CS 12th Class Past Paper Trend Analysis Report."""

import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
from collections import Counter
import re
import io
import base64
import json

# ---- Config ----
plt.rcParams.update({
    'font.family': 'DejaVu Sans',
    'font.size': 11,
    'axes.titlesize': 14,
    'axes.labelsize': 12,
    'figure.dpi': 120,
    'savefig.dpi': 120,
    'savefig.bbox': 'tight',
    'savefig.pad_inches': 0.15,
})

# Color palette — professional, accessible
C_MCQ = '#1f77b4'     # blue
C_SHORT = '#ff7f0e'   # orange
C_LONG = '#2ca02c'    # green
TYPE_COLORS = {'MCQs': C_MCQ, 'Short': C_SHORT, 'Long': C_LONG}
PALETTE = ['#1f77b4','#ff7f0e','#2ca02c','#d62728','#9467bd','#8c564b','#e377c2','#7f7f7f','#bcbd22','#17becf']

# ---- Load Data ----
df = pd.read_csv('/app/benchmark/data.csv')
df.columns = df.columns.str.strip()

# Verify columns
assert list(df.columns) == ['id', 'year', 'type', 'question']

# ---- Data Quality Check ----
# Note: year 2020 is missing from the dataset
all_years = sorted(df['year'].unique())
missing_years = set(range(2015, 2026)) - set(all_years)

# ---- Helper: chart to base64 ----
def fig_to_b64(fig):
    buf = io.BytesIO()
    fig.savefig(buf, format='png', dpi=120, bbox_inches='tight', pad_inches=0.15)
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode()
    plt.close(fig)
    return b64

# ---- KPI Calculations ----
yearly_counts = df.groupby('year').size()
yearly_type_counts = df.groupby(['year', 'type']).size().unstack(fill_value=0)
for t in ['MCQs', 'Short', 'Long']:
    if t not in yearly_type_counts.columns:
        yearly_type_counts[t] = 0
yearly_type_counts = yearly_type_counts[['MCQs', 'Short', 'Long']]
yearly_type_pct = yearly_type_counts.div(yearly_type_counts.sum(axis=1), axis=0) * 100

total_questions = len(df)
total_years = len(all_years)
avg_per_year = yearly_counts.mean()
std_per_year = yearly_counts.std()
max_year = yearly_counts.idxmax()
max_count = yearly_counts.max()
min_year = yearly_counts.idxmin()
min_count = yearly_counts.min()

# YoY change
yoy_abs = yearly_counts.diff()
yoy_pct = yearly_counts.pct_change() * 100

# Average per type
avg_per_type = yearly_type_counts.mean()

# Overall type split
overall_type = df['type'].value_counts()
overall_type_pct = (overall_type / overall_type.sum() * 100).round(1)

# ---- KPI 1: Total Questions per Year (Bar + Line chart) ----
fig1, ax1a = plt.subplots(figsize=(10, 5.2))
years_list = list(yearly_counts.index)
bars = ax1a.bar(years_list, yearly_counts.values, color=C_MCQ, alpha=0.75, width=0.6, zorder=2, label='Total Questions')
ax1a.set_xlabel('Year')
ax1a.set_ylabel('Total Questions')
ax1a.set_title('Total Questions per Year (2015–2025)')
ax1a.set_xticks(years_list)
ax1a.set_xticklabels([str(y) for y in years_list])
ax1a.axhline(y=avg_per_year, color='#d62728', linestyle='--', linewidth=1.2, label=f'Average ({avg_per_year:.1f})')
for bar, val in zip(bars, yearly_counts.values):
    ax1a.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.8, str(val), ha='center', va='bottom', fontsize=9, fontweight='bold')
ax1a.legend(loc='upper left')
ax1a.set_ylim(0, max_count * 1.18)
ax1a.yaxis.set_major_locator(mticker.MaxNLocator(integer=True))
ax1a.grid(axis='y', alpha=0.3, zorder=0)
fig1.tight_layout()
chart_total_per_year = fig_to_b64(fig1)

# ---- KPI 2: Stacked Bar — Question Type Distribution ----
