def clean_text(text):
    # Remove $ delimiter and replace with spaces
    text = text.replace('$', ' ')
    # Remove special characters but keep meaningful ones
    text = re.sub(r'[^a-zA-Z\s]', ' ', text)
    return text.lower()

def extract_topics(df_subset, n=25):
    words = []
    for q in df_subset['question']:
        cleaned = clean_text(str(q))
        tokens = cleaned.split()
        words.extend([w for w in tokens if len(w) > 2 and w not in STOP_WORDS])
    counter = Counter(words)
    return counter.most_common(n)

