    'how', 'when', 'where', 'also', 'very', 'just', 'than', 'then',
    'about', 'into', 'over', 'such', 'only', 'other', 'more', 'some',
    'these', 'those', 'one', 'two', 'three', 'four',
}

def clean_text(text):
    # Remove $ delimiter and replace with spaces
    text = text.replace('$', ' ')
    # Remove special characters but keep meaningful ones
    text = re.sub(r'[^a-zA-Z\s]', ' ', text)
    return text.lower()

def extract_topics(df_subset, n=25):
    words = []
    for q in df_subset['question']:
        cleaned = clean_text(str(q))
        tokens = cleaned.split()
        words.extend([w for w in tokens if len(w) > 2 and w not in STOP_WORDS])
    counter = Counter(words)
    return counter.most_common(n)

# Overall topics
all_topics = extract_topics(df, n=30)

# Topics by question type
topics_mcq = extract_topics(df[df['type'] == 'MCQs'], n=20)
topics_short = extract_topics(df[df['type'] == 'Short'], n=20)
topics_long = extract_topics(df[df['type'] == 'Long'], n=20)

# Topic evolution — top topics per year
topic_evolution = {}
for yr in all_years:
    df_yr = df[df['year'] == yr]
    topic_evolution[yr] = extract_topics(df_yr, n=10)

