# Count topic mentions across all years
def count_topic_mentions(df, topic_keywords):
    all_text = ' '.join(df['question'].fillna('').str.lower())
    count = 0
    for kw in topic_keywords:
        count += all_text.count(kw)
    return count

topic_category_totals = {}
for cat, keywords in TOPIC_CATEGORIES.items():
    topic_category_totals[cat] = count_topic_mentions(df, keywords)

